/**
 * A medição rádio-carbono — uma curva, sete leituras dela.
 *
 * A curva de decaimento é a mesma o tempo todo, e é ela que amarra a trilha: o
 * passo da meia-vida mostra onde ela cai pela metade, o da idade lê a fração, o
 * da contaminação mostra o ponto SALTANDO para a esquerda quando entra carbono
 * novo, e o do reservatório o mostra saltando para a direita. Trocar de figura
 * a cada passo faria parecer que são sete assuntos; é um só, visto de sete
 * ângulos.
 *
 * As duas fases que não são leitura de curva têm cena própria: a origem (o raio
 * cósmico fabricando C-14 no alto da atmosfera) e o platô (a curva de
 * calibração, que é outra curva e outro eixo).
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const MEIA_VIDA = 5730;
const CEU = '#cfe0f5';
const CEU_ALTO = '#8fb4dd';

/** Fração restante depois de `anos`, com a meia-vida que o passo estiver usando. */
function restante(anos: number, meiaVida: number): number {
  return 2 ** (-anos / Math.max(1, meiaVida));
}

const carbono: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /**
   * A curva de decaimento, e o eixo dela. Devolve os conversores, porque cada
   * fase marca um ponto diferente sobre a MESMA curva.
   */
  function curva(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    meiaVida: number,
    anosMax: number,
  ): { px: (anos: number) => number; py: (fracao: number) => number } {
    const cor = paleta();
    const x0 = L * 0.12;
    const x1 = L * 0.94;
    const yTopo = A * 0.2;
    const yBase = A * 0.76;

    const px = (anos: number): number => x0 + limitar(anos / anosMax, 0, 1) * (x1 - x0);
    const py = (fracao: number): number => yBase - limitar(fracao, 0, 1) * (yBase - yTopo);

    const miudo = limitar(A * 0.03, 8, 11);

    // Os eixos.
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x0, yTopo);
    ctx.lineTo(x0, yBase);
    ctx.lineTo(x1, yBase);
    ctx.stroke();

    // As marcas de meia-vida: é nelas que a curva conta a própria história.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    for (let n = 1; n * meiaVida <= anosMax; n++) {
      const x = px(n * meiaVida);
      ctx.setLineDash([2, 4]);
      ctx.beginPath();
      ctx.moveTo(x, yTopo);
      ctx.lineTo(x, yBase);
      ctx.stroke();
      ctx.setLineDash([]);
      if (n <= 4) {
        texto(ctx, `${n}×`, x, yBase + miudo * 1.4, miudo * 0.9, { cor: cor.fraco });
      }
    }

    for (const f of [0.25, 0.5, 1]) {
      texto(ctx, `${f * 100}%`, x0 - 4, py(f), miudo * 0.9, {
        cor: cor.fraco,
        alinhamento: 'right',
      });
    }

    // A curva.
    ctx.strokeStyle = cor.azul;
    ctx.lineWidth = 2.6;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (let i = 0; i <= 140; i++) {
      const anos = (i / 140) * anosMax;
      const x = px(anos);
      const y = py(restante(anos, meiaVida));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    texto(ctx, 'carbono-14 restante', x0 - 4, yTopo - miudo * 1.2, miudo * 0.9, {
      cor: cor.fraco,
      peso: 600,
      alinhamento: 'left',
    });
    texto(ctx, 'meia-vidas decorridas', (x0 + x1) / 2, yBase + miudo * 3, miudo * 0.9, {
      cor: cor.fraco,
      peso: 600,
    });

    return { px, py };
  }

  /** A origem: o raio cósmico que fabrica o C-14 lá em cima. */
  function origem(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const miudo = limitar(A * 0.032, 8, 11);

    const ceu = ctx.createLinearGradient(0, A * 0.16, 0, A * 0.8);
    ceu.addColorStop(0, CEU_ALTO);
    ceu.addColorStop(1, CEU);
    ctx.fillStyle = ceu;
    ctx.fillRect(0, A * 0.16, L, A * 0.64);

    // O chão, com uma planta: é por ela que o C-14 entra na vida.
    ctx.fillStyle = '#8a9c62';
    ctx.fillRect(0, A * 0.72, L, A * 0.08);

    // Os raios cósmicos, riscando de cima.
    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    for (let i = 0; i < 4; i++) {
      const fase = (t * 0.6 + i * 0.25) % 1;
      const x = L * (0.12 + i * 0.22);
      ctx.globalAlpha = 1 - fase;
      ctx.beginPath();
      ctx.moveTo(x, A * 0.16);
      ctx.lineTo(x + 10, A * (0.16 + fase * 0.16));
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // A conversão, no alto: N-14 vira C-14.
    const yReacao = A * 0.36;
    disco(ctx, L * 0.34, yReacao, Math.max(11, A * 0.045), cor.fraco);
    texto(ctx, 'N', L * 0.34, yReacao, miudo * 1.1, { cor: cor.contraste, peso: 800 });
    texto(ctx, '14', L * 0.34 + miudo, yReacao - miudo, miudo * 0.7, {
      cor: cor.contraste,
      peso: 700,
    });

    texto(ctx, '→', L * 0.47, yReacao, miudo * 1.6, { cor: cor.texto, peso: 800 });

    disco(ctx, L * 0.6, yReacao, Math.max(11, A * 0.045), cor.erro);
    texto(ctx, 'C', L * 0.6, yReacao, miudo * 1.1, { cor: cor.contraste, peso: 800 });
    texto(ctx, '14', L * 0.6 + miudo, yReacao - miudo, miudo * 0.7, {
      cor: cor.contraste,
      peso: 700,
    });

    etiqueta(ctx, 'alta atmosfera', L * 0.47, A * 0.24, miudo, cor.fraco, 700);

    // O caminho até a vida: o C-14 desce como gás carbônico e entra na planta.
    ctx.strokeStyle = cor.erro;
    ctx.lineWidth = 1.6;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(L * 0.6, yReacao + A * 0.06);
    ctx.quadraticCurveTo(L * 0.7, A * 0.58, L * 0.5, A * 0.68);
    ctx.stroke();
    ctx.setLineDash([]);

    // A planta.
    ctx.strokeStyle = '#3f7a35';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(L * 0.5, A * 0.72);
    ctx.lineTo(L * 0.5, A * 0.62);
    ctx.stroke();
    ctx.fillStyle = '#4e9c41';
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(
        L * 0.5 + lado * A * 0.03,
        A * 0.635,
        A * 0.035,
        A * 0.016,
        lado * 0.6,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }

    etiqueta(ctx, 'enquanto vive, repõe o que decai', L * 0.5, A * 0.86, miudo, cor.texto, 700);
  }

  /** O platô: a curva de calibração, com o trecho horizontal que abre a margem. */
  function planalto(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const miudo = limitar(A * 0.03, 8, 11);

    const x0 = L * 0.14;
    const x1 = L * 0.94;
    const yTopo = A * 0.22;
    const yBase = A * 0.78;

    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x0, yTopo);
    ctx.lineTo(x0, yBase);
    ctx.lineTo(x1, yBase);
    ctx.stroke();

    texto(ctx, 'idade medida', x0 - 4, (yTopo + yBase) / 2, miudo * 0.9, {
      cor: cor.fraco,
      peso: 600,
      alinhamento: 'right',
    });
    texto(
      ctx,
      'idade verdadeira (anéis de árvore)',
      (x0 + x1) / 2,
      yBase + miudo * 2,
      miudo * 0.9,
      {
        cor: cor.fraco,
        peso: 600,
      },
    );

    // A curva de calibração: sobe, mas com um trecho quase horizontal no meio.
    const cx = (u: number): number => x0 + u * (x1 - x0);
    const cy = (u: number): number => {
      // Um platô entre 40% e 62% do eixo — a mesma medida para várias idades.
      const achatado = u < 0.4 ? u : u < 0.62 ? 0.4 + (u - 0.4) * 0.08 : u - 0.2;
      return yBase - (achatado / 0.8) * (yBase - yTopo);
    };

    ctx.strokeStyle = cor.azul;
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    for (let i = 0; i <= 120; i++) {
      const u = i / 120;
      if (i === 0) ctx.moveTo(cx(u), cy(u));
      else ctx.lineTo(cx(u), cy(u));
    }
    ctx.stroke();

    // A leitura: uma medida horizontal atravessa o platô inteiro.
    const yMedida = cy(0.5);
    ctx.strokeStyle = cor.erro;
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 4]);
    ctx.beginPath();
    ctx.moveTo(x0, yMedida);
    ctx.lineTo(cx(0.62), yMedida);
    ctx.stroke();
    ctx.setLineDash([]);

    // O intervalo que essa única medida autoriza — a margem larga, desenhada.
    retangulo(
      ctx,
      cx(0.4),
      yMedida,
      cx(0.62) - cx(0.4),
      yBase - yMedida,
      0,
      'rgb(201 74 69 / 18%)',
    );
    ctx.strokeStyle = cor.erro;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(cx(0.4), yBase);
    ctx.lineTo(cx(0.62), yBase);
    ctx.stroke();

    etiqueta(ctx, 'uma medida', x0 + 4, yMedida - miudo * 1.5, miudo, cor.erro, 700, {
      alinhamento: 'left',
    });
    etiqueta(ctx, 'muitas idades possíveis', cx(0.51), yBase - miudo * 1.6, miudo, cor.erro, 800);
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const fase = textoDe(info, 'fase') || 'origem';
    const ok = info.ok === true;

    if (fase === 'origem') {
      titulo(ctx, L, A, 'Raio cósmico, nitrogênio, carbono-14');
      origem(ctx, L, A, t);
      rodape(ctx, L, A, ok, 'A fábrica fica no alto da atmosfera ✔', 'De onde ele vem?');
      return;
    }

    if (fase === 'planalto') {
      titulo(ctx, L, A, 'Onde a curva deita, a margem se abre');
      planalto(ctx, L, A);
      rodape(
        ctx,
        L,
        A,
        ok,
        'A data continua certa — e diz menos, abertamente ✔',
        'O que acontece com uma amostra que cai no trecho plano?',
      );
      return;
    }

    // ── As quatro fases que leem a mesma curva ────────────────────────────
    const meiaVida = fase === 'meiavida' ? numeroDe(info, 'meia', MEIA_VIDA) : MEIA_VIDA;
    const anosMax = fase === 'contaminacao' ? 45_000 : meiaVida * 4;
    const miudo = limitar(A * 0.032, 8, 11);

    titulo(
      ctx,
      L,
      A,
      fase === 'meiavida'
        ? 'Metade a cada meia-vida'
        : fase === 'idade'
          ? 'Da fração medida sai a idade'
          : fase === 'contaminacao'
            ? 'O carbono novo puxa a leitura para cá'
            : 'A amostra que já nasce velha',
    );

    const { px, py } = curva(ctx, L, A, meiaVida, anosMax);

    if (fase === 'meiavida') {
      // A queda pela metade, desenhada em L: desce da curva e vai ao eixo.
      const x = px(meiaVida);
      ctx.strokeStyle = ok ? cor.verde : cor.ouro;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(px(0), py(0.5));
      ctx.lineTo(x, py(0.5));
      ctx.stroke();
      disco(ctx, x, py(0.5), 5, ok ? cor.verde : cor.ouro);
      etiqueta(
        ctx,
        `${ptBR(Math.round(meiaVida))} anos → metade`,
        x,
        py(0.5) - miudo * 1.8,
        miudo,
        ok ? cor.verde : cor.ouro,
        800,
      );
    }

    if (fase === 'idade') {
      const idade = numeroDe(info, 'idade', 0);
      const fracao = restante(idade, MEIA_VIDA);

      // A meta: os 25% que o laboratório mediu.
      ctx.strokeStyle = cor.verde;
      ctx.lineWidth = 1.6;
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      ctx.moveTo(px(0), py(0.25));
      ctx.lineTo(px(anosMax), py(0.25));
      ctx.stroke();
      ctx.setLineDash([]);
      etiqueta(ctx, 'medido: 25%', px(anosMax), py(0.25) - miudo * 1.5, miudo, cor.verde, 700, {
        alinhamento: 'right',
      });

      disco(ctx, px(idade), py(fracao), 6, ok ? cor.verde : cor.azul);
      etiqueta(
        ctx,
        `${ptBR(Math.round(idade))} anos`,
        px(idade),
        py(fracao) - miudo * 1.8,
        miudo,
        ok ? cor.verde : cor.azul,
        800,
      );
    }

    if (fase === 'contaminacao') {
      const real = numeroDe(info, 'real', 40_000);
      const medida = numeroDe(info, 'medida', real);
      const fReal = restante(real, MEIA_VIDA);
      const fMedida = restante(medida, MEIA_VIDA);

      // A verdade, e para onde a sujeira levou a leitura.
      disco(ctx, px(real), py(fReal), 6, cor.fraco);
      // Abaixo do ponto: as duas leituras caem quase na mesma altura da curva,
      // e as duas etiquetas por cima se sobrepunham.
      etiqueta(ctx, 'idade real', px(real), py(fReal) + miudo * 2, miudo, cor.fraco, 700, {
        alinhamento: 'right',
      });

      ctx.strokeStyle = cor.erro;
      ctx.lineWidth = 2.2;
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(px(real), py(fReal));
      ctx.lineTo(px(medida), py(fMedida));
      ctx.stroke();
      ctx.setLineDash([]);

      disco(ctx, px(medida), py(fMedida), 6, ok ? cor.verde : cor.erro);
      etiqueta(
        ctx,
        `lido: ${ptBR(Math.round(medida / 100) * 100)} anos`,
        px(medida),
        py(fMedida) - miudo * 1.8,
        miudo,
        ok ? cor.verde : cor.erro,
        800,
      );
    }

    if (fase === 'reservatorio') {
      const reservatorio = numeroDe(info, 'reservatorio', 0);
      const medido = 3000;
      const verdadeiro = medido - reservatorio;

      // A concha mede daqui; o bicho viveu dali. O vão entre os dois é o desconto.
      disco(ctx, px(medido), py(restante(medido, MEIA_VIDA)), 6, cor.fraco);
      etiqueta(
        ctx,
        'a concha mede',
        px(medido),
        py(restante(medido, MEIA_VIDA)) - miudo * 1.7,
        miudo,
        cor.fraco,
        700,
      );

      ctx.strokeStyle = ok ? cor.verde : cor.azulClaro;
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(px(medido), py(restante(medido, MEIA_VIDA)));
      ctx.lineTo(px(verdadeiro), py(restante(verdadeiro, MEIA_VIDA)));
      ctx.stroke();

      disco(ctx, px(verdadeiro), py(restante(verdadeiro, MEIA_VIDA)), 6, ok ? cor.verde : cor.azul);
      etiqueta(
        ctx,
        `viveu há ${ptBR(verdadeiro)} anos`,
        px(verdadeiro),
        py(restante(verdadeiro, MEIA_VIDA)) + miudo * 2.2,
        miudo,
        ok ? cor.verde : cor.azul,
        800,
      );
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      'Fecha ✔',
      fase === 'meiavida'
        ? 'Arraste até a curva cruzar os 50%.'
        : fase === 'idade'
          ? 'Arraste até a curva cruzar a linha dos 25%.'
          : fase === 'contaminacao'
            ? 'Aumente o carbono moderno e veja a leitura despencar.'
            : 'Desconte o reservatório até achar quando o bicho viveu.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default carbono;
